import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.B8TleWq7.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function l(r,e,d,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Current version: <strong>0.2.0</strong>. This page is generated from <code>CHANGELOG.md</code> in the Keel repo by <code>npm run gen:changelog</code>; edit that file, not this one.</p><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Keel Setup</strong>, a Studio plugin (<code>tools/KeelSetup.lua</code>, an owned file) that creates the six root Folders and the optional place attributes, and lists the Script Sync connects still to make. Studio cannot script the connect itself, and a template place file does not keep the connections, so the connects stay manual.</li><li><code>keel.js new</code> prints the plugin install step and the next steps in Studio.</li><li>A documentation site in <code>site/</code> (VitePress): getting started, tutorials, guides, an API reference generated from the source, and a changelog page. Not copied into games.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Releasing now requires every change to be documented in the same release, with deprecations, new features and kits recorded in the changelog (see <code>site/guides/releasing-keel.md</code>).</li></ul><h3 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. After <code>node tools/keel.js update v0.2.0</code> a game has <code>tools/KeelSetup.lua</code>; copy it into Studio&#39;s Plugins folder if you want the plugin.</li></ul><h2 id="_0-1-1" tabindex="-1">0.1.1 <a class="header-anchor" href="#_0-1-1" aria-label="Permalink to &quot;0.1.1&quot;">​</a></h2><p><code>keel.js</code> writes text files with LF line endings (a Windows clone had CRLF, which StyLua rejected). New games get a <code>.gitattributes</code> that keeps LF on checkout.</p><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><p>First version. Extracted from StealTheGun (commit <code>7831be3</code>): Loader, Scheduler, Signal, Trove, Log, Net (Packet), Defs, Entity, Data (ProfileStore), State and Replica, Client layer (Input, UIController, View, Widget), Console (Cmdr), Purchases, Policy, LiveDefs, the unit test runner and its specs, plus the starter game files, tooling and notes.</p>',13)])])}const p=t(i,[["render",l]]);export{u as __pageData,p as default};
